(function($){"use strict";$(function(){$(document).on("click",".joinchat_phone__add",function(e){e.preventDefault();var $wrap=$(this).parent(),$zero=$wrap.find(".joinchat_phone").first(),key=Math.floor(Math.random()*1e5),base=$zero.attr("name")||$zero.data("name")||"joinchat[telephone][0]",name=base.replace(/\[(\d+)\]([^\[\]]*)$/,"["+key+"]$2");$('<br><input class="joinchat_phone" name="'+name+'" value="" type="text" autocomplete="off">').insertBefore(this);$wrap.find(".joinchat_phone").last().trigger("focus")});$(document).on("keydown",".joinchat_phones .joinchat_phone",function(e){var key=e.which||e.keyCode,$input=$(this);if(key!==8||$input.val()!=="")return;e.preventDefault();var $prev=$input.prevAll(".joinchat_phone").first();if($prev.length){$prev.trigger("focus");$input.prev("br").remove();$input.remove()}})})})(jQuery);
